local GoodsNodePath = "Game.Behaviours.GoodNodeMB"
local ConvertNodePath = "Game.UI.Convert.MatCompositeCellMB"
local cardConfMgr = CardConfMgr:GetInstance()
local goodsConfMgr = GoodsConfMgr:GetInstance()

local GridViewPrefabName = 'CompositeCellNode'
