--- from: Assets/BundleResources/Prefabs/MaterialComposite/MaterialComposite.prefab
---@class MatConvertPreviewDialog
---@field Env                            MatConvertPreviewDialog
---@field controller                        Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field BtnClose                        UnityEngine.RectTransform
---@field FontStyleButton                UnityEngine.RectTransform
---@field MaxButton                        UnityEngine.RectTransform
---@field MinButton                        UnityEngine.RectTransform
---@field MinusButton                    UnityEngine.RectTransform
---@field PlusButton                        UnityEngine.RectTransform
---@field InputField                        TMPro.TMP_InputField
---@field NumText                        TMPro.TextMeshProUGUI
---@field LabelText                        UnityEngine.UI.Text
---@field NameText                        UnityEngine.UI.Text
---@field GoodNode                        UnityEngine.RectTransform
---@field GridView                        SuperScrollView.LoopGridView
local MatConvertPreviewDialog = Class("MatConvertPreviewDialog")

local MAX_NO = 99

function MatConvertPreviewDialog:__init()
    self._gainId = nil
    self._gainNo = 0
    self._maxNo = MAX_NO
    self._isEnough = true
    self.data = nil
    self.initialed = false
    self.consume = { }
    self.selectIndex = 1
end

function MatConvertPreviewDialog:__delete()
    self.controller = nil
    self._gainId = nil
    self._gainNo = nil
    self._isEnough = nil
    self.data = nil
    self.initialed = nil
    self.consume = nil
end

function MatConvertPreviewDialog:Awake()
    ---@type Engine.UI.UIArgument
    local argument = self.controller.Argument
    if isSet(argument, "parameters") then
        self._gainId = checkInt(argument.parameters.gainId)
        self._gainNo = checkInt(argument.parameters.num)
        print('--->>', table.dump(argument.parameters))
    end

    self.data = self:InitData(self._gainId)

    SetButtonAction(self.MinButton, function()
        ---设置最小值
        self._gainNo = 1
        self:FreshUI()
    end)

    SetButtonAction(self.BtnClose, function()
        UIModule.CloseDialog(self.controller)
    end)
    SetButtonAction(self.MaxButton, function()
        ---设置最小值
        self._gainNo = self._maxNo
        self._gainNo = math.max(1, self._maxNo)
        self:FreshUI()
    end)
    SetButtonAction(self.MinusButton, function()
        ---减少
        local _gainNo = self._gainNo
        if _gainNo > 1 then
            _gainNo = _gainNo - 1
        end
        self._gainNo = math.max(1, _gainNo)
        self:FreshUI()
    end)
    SetButtonAction(self.PlusButton, function()
        ---减少
        local _gainNo = self._gainNo
        if _gainNo < self._maxNo then
            _gainNo = _gainNo + 1
        end
        ---防止加一个变成了0
        self._gainNo = math.max(1, math.min(self._maxNo, _gainNo))
        self:FreshUI()
    end)

    SetButtonAction(self.FontStyleButton, function()
        if self._gainNo <= 0 then
            GameUtils.Toast(localize("当前材料不足不能进行合成"))
            return
        end
        ---合成的按钮的逻辑
        ---@type MatCompositeVo
        local vo = self.data[self.selectIndex]
        local consumeNo = (checkInt(vo.costItemNum) * checkInt(self._gainNo))
        local haveNo = GoodsUtils.GetThingNo(vo.costItem)
        if haveNo < consumeNo then
            GameUtils.Toast(localize("材料不足不能合成"))
            return
        end
        GameUtils.SecondConfirm(localize('是否进行合成'), function()
            GameUtils.Request(Interfaces.BackpackComposite, {
                id = vo.id, num = checkInt(self._gainNo)
            }, function(request, responseTable)
                if checkTable(responseTable) and isSet(responseTable, "errCode") then
                    local code = checkNumber(responseTable.errCode)
                    if code == 0 then
                        local t = {}
                        table.insert(t, { goodsId = vo.costItem, num = -(checkInt(vo.costItemNum) * checkInt(self._gainNo)) })
                        GoodsUtils.DrawRewards(t)
                        ----合成成功了
                        local responseData = checkTable(responseTable.data)
                        if isSet(responseData, "rewards") then
                            if #responseData.rewards > 0 then
                                ---然后播放动画的逻辑
                                GoodsUtils.DrawRewards(responseData.rewards)
                                Events.Broadcast(Constants.EventNames.UIEventCompositeFreshGridView)
                                self:FreshUI()
                                ---弹出奖励框
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                            else
                                GameUtils.Toast(localize("沒有可領取的物品"))
                            end
                        end
                    end
                end
            end)
        end)
    end)

    self.InputField.onEndEdit:AddListener(function(num)
        num = checkNumber(num)
        if num < 1 then
            num = 1
            --GameUtils.Toast(localize("输入数值超过下限"))
        elseif num > self._maxNo then
            --GameUtils.Toast(localize("输入数值超过上限"))
            num = self._maxNo
        end
        self._gainNo = num
        self:FreshUI()
    end)
end

function MatConvertPreviewDialog:InitData(gainId)
    local gainIdGroup = {}
    local setting = CfUtils.GetCf(AutoIds.IdSetting411, "MatCompositeVo")
    local tableSettings = setting:GetAll()
    for _, vo in pairs(tableSettings) do
        if checkNumber(vo.gainVo.goodsId) == gainId then
            table.insert(gainIdGroup, vo)
        end
    end
    return gainIdGroup
end

---FreshGainNode
---合成节点的刷新
---@param vo MatCompositeVo
---@param goodsVo GoodsVo
function MatConvertPreviewDialog:FreshGainNode(vo, goodsVo)
    local goodItemNodeMB = GetLuaBehaviour(self.GoodNode.gameObject, GoodsNodePath)
    if not isNull(goodItemNodeMB) then
        if isNull(goodItemNodeMB.Env) then
            goodItemNodeMB:Init()
        end
        ---@type GoodNodeMB
        local goodNodeEnv = goodItemNodeMB.Env
        local num = checkInt(vo.gainVo.goodsNum) * checkInt(self._gainNo)
        goodNodeEnv:Reload({
            goodsId = vo.gainVo.goodsId, isShowNo = false
        })
        self.NameText.text = tostring(goodsVo.name)
        local thingNo = GoodsUtils.GetThingNo(vo.gainVo.goodsId)
        self.NumText.text = format4bit(thingNo)
    end
end

---FreshUI
function MatConvertPreviewDialog:FreshUI()
    ---@type MatCompositeVo
    local vo = self.data[self.selectIndex]
    local gainId = vo.gainVo.goodsId
    local goodsVo = goodsConfMgr:GetGoodsVoById(gainId)
    if isNull(goodsVo) then
        printError("%d not exists", gainId)
        return
    end

    ----计算消耗的最大项，得到合成可得最大量
    local haveNo = GoodsUtils.GetThingNo(vo.costItem)
    local costNum = checkNumber(vo.costItemNum)
    self._maxNo = math.floor(haveNo / costNum)
    print(self._gainNo, self._maxNo)
    if self._maxNo > 0  and self._gainNo == 0 then
        self._gainNo = 1
    end
    if self._gainNo > self._maxNo then
        self._gainNo = self._maxNo
    end
    self:FreshGridView()
    if self._gainNo > 0 then
        self.InputField.text = tostring(math.min(self._gainNo, self._maxNo))
    else
        self.InputField.text = '0'
    end
    self:FreshGainNode(vo, goodsVo)
end

---FreshGridView
---刷新复合类型的列表
function MatConvertPreviewDialog:FreshGridView()
    if not self.initialed then
        self.GridView:InitGridView(#self.data, Bind(self, self.OnGetGridItemByIndex))
        self.initialed = true
    else
        GameUtils.ReloadData(self.GridView, #self.data)
    end

end

---OnGetGridItemByIndex
---@param gridView SuperScrollView.LoopGridView
---@param index number
---@param row number
---@param column number
function MatConvertPreviewDialog:OnGetGridItemByIndex(gridView, index, row, column)
    if index < 0 then
        return
    end
    local cell = gridView:NewListViewItem(GridViewPrefabName)
    local position = index + 1
    ---@type MatCompositeVo
    local vo = self.data[position]
    local goodsId = vo.costItem
    local goodItemNodeMB = GetLuaBehaviour(cell.gameObject, ConvertNodePath)
    if not IsNull(goodItemNodeMB) then
        if IsNull(goodItemNodeMB.Env) then
            goodItemNodeMB:Init()
        end
        ---@type MatCompositeCellMB
        local goodItemNodeEnv = goodItemNodeMB.Env
        local goodsNum = checkNumber(vo.costItemNum)
        local myNo = GoodsUtils.GetThingNo(checkInt(goodsId))
        goodItemNodeEnv:Reload(vo, position, function(data, position)
            ---不前选中状态
            if position == self.selectIndex then
                return
            end
            self.selectIndex = position
            self:FreshUI()
        end, myNo, goodsNum, self.selectIndex == position)
    end
    return cell
end

function MatConvertPreviewDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --更新的逻辑
        self:FreshUI()
    end))
    return coWait
end

function MatConvertPreviewDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return MatConvertPreviewDialog